void runParameterizedTest(String name, List<Object[]> cases, BiConsumer<Object[], ItemDao> logic) {
  for (int i = 0; i < cases.size(); i++) {
    int idx = i;
    runTest(name + "[" + idx + "]", () -> logic.accept(cases.get(idx), dao));
  }
}

