static void runTest(String name, TestCase test) {
  try { test.run(); passed++; System.out.println("[PASSED] " + name); }
  catch (...) { failed++; System.out.println("[FAILED] " + name); }
  finally { tearDown(name); }
}

Map<String, int[]> stats = new HashMap<>();
void runTest(String category, String name, TestCase test) {
  stats.putIfAbsent(category, new int[2]);
  try { test.run(); stats.get(category)[0]++; } catch (...) { stats.get(category)[1]++; }
}

